using System.Text.RegularExpressions;
using UnityEngine;using UnityEngine.UI;
namespace ElDespacho {
 // Only interface labels, never political dialogue or evidence. Source text is restored on OFF.
 public sealed class AccessMeaning:MonoBehaviour {
  Text label;string original,last;
  void Awake(){label=GetComponent<Text>();original=label.text;}
  public static bool Supports(Text t){string s=AccessController.Plain(t.text).Trim();return s.StartsWith("Países por atender")||s=="Alianza: tu bloque"||s=="Rumor: posible amenaza"||s=="Rumor: posible aliado"||s=="Pendiente de visita"||s=="Lazos cortados"||s=="En ruinas"||s.StartsWith("LO QUE TRAE EL NUEVO AÑO")||s=="No hay opción de esperar.\nDecide."||s=="ESTABILIDAD"||s=="SEGURIDAD"||s=="PROSPERIDAD"||s=="APROBADO"||s=="DENEGADO"||s=="DOSSIER"||s=="INTELIGENCIA"||s=="COMERCIO"||s=="REGIÓN Y RIESGO"||s.StartsWith("Estabilidad  ")||s.StartsWith("Seguridad  ")||s.StartsWith("Prosperidad  ")||Regex.IsMatch(s,@"^(Estabilidad|Seguridad|Prosperidad)\s*[+−-]\d");}
  public void Apply(){if(label==null)return;if(last!=null&&label.text!=last)original=label.text;string s=original; if(AccessPreferences.Current.symbols){string plain=AccessController.Plain(s).Trim();if(plain=="Alianza: tu bloque")s="[ALIADO] "+s;else if(plain=="Rumor: posible amenaza")s="[!] "+s;else if(plain=="Rumor: posible aliado")s="[+] "+s;else if(plain=="Pendiente de visita")s="[?] "+s;else if(plain=="Lazos cortados"||plain=="En ruinas")s="[V] "+s;else if(plain=="APROBADO")s="[OK] "+s;else if(plain=="DENEGADO")s="[NO] "+s;else if(plain=="DOSSIER"||plain=="INTELIGENCIA"||plain=="COMERCIO"||plain=="REGIÓN Y RIESGO")s="[i] "+s;else if(plain.StartsWith("Estabilidad")||plain=="ESTABILIDAD")s="[=] "+s;else if(plain.StartsWith("Seguridad")||plain=="SEGURIDAD")s="[S] "+s;else if(plain.StartsWith("Prosperidad")||plain=="PROSPERIDAD")s="[$] "+s;}if(AccessPreferences.Current.simpleLanguage){if(AccessController.Plain(original).StartsWith("LO QUE TRAE EL NUEVO AÑO"))s="PASOS: Lea las noticias y sus efectos. Después pulse el botón para continuar el mandato.\n\n"+s;else if(original=="No hay opción de esperar.\nDecide.")s="Elija alianza o cortar lazos. La decisión se aplica al pulsar.";else if(Regex.IsMatch(AccessController.Plain(original),@"^(Estabilidad|Seguridad|Prosperidad)\s*[+−-]\d"))s+="\nUn + aumenta ese indicador; un - lo reduce. Revise el resultado y continúe.";}if(AccessPreferences.Current.textScale>=1.5f&&AccessController.Plain(original).StartsWith("Países por atender"))s=original.Replace("Países por atender","Pendientes");label.text=last=s;}
 }
 public sealed partial class AccessController {
  Canvas contextGlossaryCanvas;Button contextGlossaryButton;
  void UpdateContextGlossary(){
   bool show=P.glossary&&(game.ScreenName!="Despacho"||menus.PageName=="Consulta")&&page==""&&!reader&&game.HasSession&&(!menus.IsVisible||menus.PageName=="Consulta");
   if(show&&contextGlossaryCanvas==null){var go=new GameObject("ContextGlossary",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));go.transform.SetParent(transform,false);contextGlossaryCanvas=go.GetComponent<Canvas>();contextGlossaryCanvas.renderMode=RenderMode.ScreenSpaceOverlay;contextGlossaryCanvas.sortingOrder=650;var sc=go.GetComponent<CanvasScaler>();sc.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;sc.referenceResolution=new Vector2(1920,1080);contextGlossaryButton=Kit.MakeButton(go.transform,"GLOSARIO",14,Pal.WoodLight,Pal.Cream,()=>OpenCategory("Glosario"),new Vector2(.88f,.908f),new Vector2(.995f,.935f));contextGlossaryButton.name="ContextGlossaryButton";}
   var launch=transform.Find("PauseShortcut");if(launch!=null){var pause=launch.GetComponentInChildren<Button>();if(pause!=null){var pr=(RectTransform)pause.transform;bool large=P.textScale>=1.5f;var pl=pause.GetComponentInChildren<Text>();pl.text=large?"PAUSA":"PAUSA · ESC";pr.anchorMin=new Vector2(.89f,large?.85f:.909f);pr.anchorMax=new Vector2(.99f,large?.892f:.936f);}}
   if(contextGlossaryCanvas!=null){contextGlossaryCanvas.enabled=show;var br=(RectTransform)contextGlossaryButton.transform;bool big=P.textScale>=1.5f;br.anchorMin=new Vector2(.88f,big?.806f:.875f);br.anchorMax=new Vector2(.995f,big?.846f:.905f);var t=contextGlossaryButton.GetComponentInChildren<Text>();t.enabled=true;t.resizeTextForBestFit=false;t.verticalOverflow=VerticalWrapMode.Overflow;t.rectTransform.offsetMin=t.rectTransform.offsetMax=Vector2.zero;t.fontSize=Mathf.RoundToInt(14*P.textScale);t.color=DeskPreferences.Current.highContrast?Color.white:Pal.Cream;contextGlossaryButton.targetGraphic.color=DeskPreferences.Current.highContrast?Color.black:Pal.WoodLight;}
  }
 }
}
